def word_count_ascii(text):
    words = []
    current = []
    for ch in text:
        if ('A' <= ch <= 'Z') or ('a' <= ch <= 'z'):
            current.append(ch)
        else:
            if current:
                words.append(''.join(current))
                current = []
    if current:
        words.append(''.join(current))
    lower_words = [w.lower() for w in words]
    counts = {}
    for w in lower_words:
        counts[w] = counts.get(w, 0) + 1
    result = [[w, counts[w]] for w in counts]
    result.sort(key=lambda x: x[0])
    return result

