def word_count_ascii(text: str) -> list:
    """Return [word, count] pairs for ASCII-letter runs, sorted lexicographically."""
    words = []
    current = []
    for ch in text:
        o = ord(ch)
        if 65 <= o <= 90 or 97 <= o <= 122:  # A-Z or a-z
            current.append(ch)
        else:
            if current:
                words.append(''.join(current).lower())
                current.clear()
    if current:
        words.append(''.join(current).lower())
    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    return sorted([[w, c] for w, c in counts.items()])
```

